-- 911 Analytics — schema initial
-- À exécuter une seule fois dans l'éditeur SQL de ton projet Supabase
-- (Dashboard > SQL Editor > New query > coller > Run)

create table if not exists public.listings (
  id text primary key,
  model text not null,
  generation text not null,
  phase text not null,
  image text not null,
  price integer not null,
  mileage integer not null,
  year integer not null,
  power integer not null,
  fuel_type text not null,
  transmission text not null,
  country text not null,
  country_flag text not null,
  city text not null,
  seller text not null,
  seller_type text not null,
  seller_rating numeric not null,
  seller_phone text not null,
  seller_email text not null,
  listing_url text not null,
  listing_source text not null,
  conformity integer not null,
  published_days_ago integer not null,
  options jsonb not null default '[]'::jsonb,
  vigilance_points jsonb not null default '[]'::jsonb,
  negotiation_arguments jsonb not null default '[]'::jsonb,
  price_history jsonb not null default '[]'::jsonb,
  value_analysis jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

alter table public.listings enable row level security;

-- Tout le monde peut lire les annonces (c'est un moteur de recherche public).
-- Aucune policy d'insert/update/delete n'est créée : par défaut, RLS refuse
-- ces opérations pour la clé "anon" utilisée par le frontend.
create policy "Public read access on listings"
  on public.listings for select
  using (true);
insert into public.listings (
  id, model, generation, phase, image,
  price, mileage, year, power, fuel_type, transmission,
  country, country_flag, city, seller, seller_type,
  seller_rating, seller_phone, seller_email, listing_url, listing_source,
  conformity, published_days_ago, options, vigilance_points,
  negotiation_arguments, price_history, value_analysis
) values
  ('1', '911 Carrera S', '997', 'Phase I', 'https://images.pexels.com/photos/36626909/pexels-photo-36626909.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 42500, 82000, 2005, 355, 'Essence', 'Manuelle', 'France', 'FR', 'Lyon', 'Auto Lyon Premium', 'Professionnel', 4.2, '+33 4 78 00 00 01', 'contact@autolyonpremium.fr', 'https://www.leboncoin.fr/voiture/911-carrera-s-997-1', 'LeBonCoin', 72, 2, '[{"key":"x51","label":"X51 Powerkit","present":false},{"key":"pse","label":"Échappement Sport PSE","present":true},{"key":"chrono","label":"Chrono Plus","present":true},{"key":"sportSeats","label":"Sièges Sport","present":false},{"key":"sportChrono","label":"Pack Sport Chrono","present":false},{"key":"carbonBrakes","label":"Freins Carbone PCCB","present":false}]'::jsonb, '[{"severity":"critical","title":"Alerte Cylindres Rayés","description":"Moteur 3.8 Phase I — risque connu de rayures de cylindre. Test Piwi impératif + contrôle compression."},{"severity":"warning","title":"Embrayage non documenté","description":"Aucune facture de remplacement mentionnée. Budget prévisionnel ~1 200 € à prévoir."},{"severity":"info","title":"IMS non confirmé","description":"Roulement IMS original potentiellement non remplacé. Demander preuve ou prévoir remplacement."}]'::jsonb, '["Absence du kit X51 et sièges sport — options représentant ~4 500 € à neuf, manquantes sur ce modèle.","Kilométrage supérieur à 80 000 km sans preuve de vidange boîte PDK récente — risque de surcoût immédiat.","Aucune facture d''embrayage — argument fort pour obtenir une remise de 1 500 à 2 000 €."]'::jsonb, '[{"year":2005,"price":95000},{"year":2007,"price":72000},{"year":2009,"price":55000},{"year":2011,"price":42000},{"year":2013,"price":36000},{"year":2015,"price":33000},{"year":2017,"price":32000},{"year":2019,"price":34000},{"year":2021,"price":38000},{"year":2023,"price":41000},{"year":2025,"price":43000},{"year":2026,"price":42500}]'::jsonb, '{"retentionScore":6.5,"rarityLabel":"Modérée","trend":"stable","trend