  ('2', '911 Carrera S', '997', 'Phase II', 'https://images.pexels.com/photos/31636698/pexels-photo-31636698.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 58900, 51000, 2009, 385, 'Essence', 'Automatique / PDK', 'France', 'FR', 'Bordeaux', 'Particulier', 'Particulier', 4.5, '+33 5 56 00 00 02', 'particulier.bordeaux@example.fr', 'https://www.lacentrale.fr/annonce-911-997-2', 'La Centrale', 85, 1, '[{"key":"x51","label":"X51 Powerkit","present":true},{"key":"pse","label":"Échappement Sport PSE","present":true},{"key":"chrono","label":"Chrono Plus","present":true},{"key":"sportSeats","label":"Sièges Sport","present":true},{"key":"sportChrono","label":"Pack Sport Chrono","present":true},{"key":"carbonBrakes","label":"Freins Carbone PCCB","present":false}]'::jsonb, '[{"severity":"warning","title":"Distribution à vérifier","description":"Courroie accessoire à 60 000 km non facturée. Contrôle visuel recommandé."},{"severity":"info","title":"Coque PCM 3.0","description":"Mise à jour firmware PCM conseillée pour compatibilité Bluetooth récente."},{"severity":"info","title":"Pneus arrière","description":"Usure estimée à 40 % restant. Négociable sur le prix ou remplacement à demander."}]'::jsonb, '["Pneus arrière à 40 % d''usure restant — demande de remplacement ou remise de 600 € justifiée.","Courroie accessoire non facturée à 60 000 km — intervention à programmer, ~350 € à négocier.","Prix affiché 5 % au-dessus de la cote Argus pour cette configuration — marge de négociation de 2 500 à 3 000 €."]'::jsonb, '[{"year":2009,"price":105000},{"year":2011,"price":82000},{"year":2013,"price":62000},{"year":2015,"price":50000},{"year":2017,"price":45000},{"year":2019,"price":47000},{"year":2021,"price":52000},{"year":2023,"price":56000},{"year":2025,"price":59500},{"year":2026,"price":58900}]'::jsonb, '{"retentionScore":8.5,"rarityLabel":"Élevée","trend":"up","trendLabel":"Plus-value attendue","factors":["Fiabilité moteur grandement améliorée (DFI, plus de cylindres rayés)","Boîte PD